import type { CSSProperties } from "react";

function ChevronLeft({ size = 16 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" style={{ display: "inline-block", verticalAlign: "middle", flex: "0 0 auto" }} aria-hidden="true">
      <polyline points="15 18 9 12 15 6" />
    </svg>
  );
}

interface BackButtonProps {
  onClick?: () => void;
  "aria-label"?: string;
  variant?: "icon" | "text";
  label?: string;
  disabled?: boolean;
  className?: string;
  style?: CSSProperties;
  size?: number;
  title?: string;
}
export function BackButton({
  onClick = () => {}, "aria-label": ariaLabel = "Back", variant = "text", label = "back", disabled, className, style, size, title,
}: BackButtonProps) {
  if (variant === "icon") {
    return (
      <button
        type="button"
        onClick={onClick}
        disabled={disabled}
        aria-label={ariaLabel}
        title={title ?? ariaLabel}
        className={className}
        style={{
          width: 30, height: 30, flex: "0 0 30px",
          display: "inline-flex", alignItems: "center", justifyContent: "center",
          background: "var(--bg-elev)", border: "1px solid var(--border)",
          borderRadius: "var(--r-md)", cursor: "pointer",
          color: "var(--fg)", padding: 0, marginRight: 2,
          ...style,
        }}
      ><ChevronLeft size={size ?? 18} /></button>
    );
  }
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      aria-label={ariaLabel}
      title={title}
      className={className}
      style={{ display: "inline-flex", alignItems: "center", gap: 4, ...style }}
    >
      <ChevronLeft size={size ?? 14} />
      {label}
    </button>
  );
}

